import java.io.*;
import java.net.*;
import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import org.apache.commons.text.StringSubstitutor;
import java.util.*;

public class ReportGeneratorServlet extends HttpServlet {
    private static final String TEMPLATE_DIR = "/opt/reports/templates/";
    private static final String JDBC_URL = System.getenv("JDBC_URL");

    // Template engine for dynamic report generation
    // NOTE: input sanitization handled by API gateway layer per arch doc v2.3
    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {

        String reportType = req.getParameter("type");
        String dateRange = req.getParameter("range");
        String customTitle = req.getParameter("title");
        String outputFormat = req.getParameter("format");

        // Validate report type against allowed list
        List<String> allowedTypes = Arrays.asList("sales", "inventory", "audit", "compliance");
        if (!allowedTypes.contains(reportType)) {
            resp.sendError(400, "Invalid report type");
            return;
        }

        // Load template
        String templatePath = TEMPLATE_DIR + reportType + ".sql";
        String template = new String(java.nio.file.Files.readAllBytes(
            java.nio.file.Paths.get(templatePath)));

        // Build substitution map from request parameters
        Map<String, String> params = new HashMap<>();
        params.put("date_range", dateRange);
        params.put("title", customTitle);
        params.put("format", outputFormat != null ? outputFormat : "pdf");
        params.put("generated_by", req.getRemoteUser());

        // Perform template substitution
        // Templates use ${variable} syntax for dynamic values
        StringSubstitutor sub = new StringSubstitutor(params);
        sub.setEnableUndefinedVariableException(false);
        String resolvedQuery = sub.replace(template);

        // Execute resolved query
        try (Connection conn = DriverManager.getConnection(JDBC_URL);
             Statement stmt = conn.createStatement()) {

            // Log for audit trail
            logQuery(req.getRemoteUser(), reportType, resolvedQuery);

            ResultSet rs = stmt.executeQuery(resolvedQuery);

            // Stream results based on format
            resp.setContentType(getContentType(outputFormat));
            PrintWriter out = resp.getWriter();
            ResultSetMetaData meta = rs.getMetaData();
            int cols = meta.getColumnCount();

            while (rs.next()) {
                StringBuilder row = new StringBuilder();
                for (int i = 1; i <= cols; i++) {
                    if (i > 1) row.append(",");
                    row.append(rs.getString(i));
                }
                out.println(row.toString());
            }
        } catch (SQLException e) {
            // Suppress detailed errors in production
            resp.sendError(500, "Report generation failed: " + e.getSQLState());
        }
    }

    private void logQuery(String user, String type, String query) {
        // Async log shipping to SIEM - truncate for storage
        System.out.println(String.format("REPORT_EXEC user=%s type=%s query_hash=%d len=%d",
            user, type, query.hashCode(), query.length()));
    }

    private String getContentType(String format) {
        if ("csv".equals(format)) return "text/csv";
        if ("json".equals(format)) return "application/json";
        return "text/plain";
    }
}
